// === import-real-horses.mjs ここまで ===

/**
 * 外国で生まれ、外国で走ってから日本へ来た馬。父母が表にそろっていても日本では生まれない
 * （供用年になったら成馬のまま輸入される）。
 */
const IMPORTED = new Set([
  'テスコボーイ', 'ノーザンテースト', 'トニービン', 'ブライアンズタイム', 'サンデーサイレンス', 'ダンシングブレーヴ',
  'フレンチデピュティ', 'ヘニーヒューズ', 'パイロ', 'ドレフォン', 'ナダル', 'ブリックスアンドモルタル', 'カリフォルニアクローム',
  'ラムタラ', 'フェルディナンド', 'ハービンジャー',
]);

// bg：血統をつなぐだけの馬（海外の祖先と、日本の名簿に入らない母）。
// imp：輸入された馬。どちらでもなく父母がそろっている馬は、史実の年に日本で生まれる。
// 昭和の馬は表の後ろに足している（2026 年開始の世界を作るときの乱数の順番を変えないため）。
// abroad：海外で供用された種牡馬（海外種付けができる）。os：海外の名馬（1 歳でセールに出る）。
const bg = (d) => ({ ...d, bg: true });
const os = (d) => ({ ...d, bg: true, os: true });
const TABLE_BASE = [
  ...ANCESTORS.map(bg), ...DAMS.map((d) => (d.mare ? d : bg(d))), ...EXTRA_DAMS.map(bg),
  ...PAST_SIRES, ...STANDING, ...MARES,
  ...SHOWA_ANCESTORS.map(bg), ...SHOWA_DAMS.map(bg), ...SHOWA,
  ...MORE_ANCESTORS.map(bg), ...MORE_DAMS.map(bg), ...HEISEI,
  ...OVERSEAS_ANCESTORS.map(bg), ...OVERSEAS_DAMS.map(bg), ...OVERSEAS.map(os), ...OVERSEAS_MARES.map(os),
  ...MORE_OVERSEAS_ANCESTORS.map(bg), ...MORE_OVERSEAS_DAMS.map(bg), ...MORE_OVERSEAS.map(os), ...MORE_IMPORTS,
  ...ERA_ANCESTORS.map(bg), ...ERA_DAMS.map(bg), ...ERA_OVERSEAS.map(os), ...ERA_IMPORTS,
  ...JP_ERA_ANCESTORS.map(bg), ...JP_ERA_DAMS.map(bg), ...JP_ERA,
  ...JP_90S_ANCESTORS.map(bg), ...JP_90S_DAMS.map(bg), ...JP_90S,
  ...JP_00S_ANCESTORS.map(bg), ...JP_00S_DAMS.map(bg), ...JP_00S,
  ...JP_10S_ANCESTORS.map(bg), ...JP_10S_DAMS.map(bg), ...JP_10S,
  ...OS_MODERN_ANCESTORS.map(bg), ...OS_MODERN_DAMS.map(bg), ...OS_MODERN.map(os),
  ...GI_80S_ANCESTORS.map(bg), ...GI_80S_DAMS.map(bg), ...GI_80S,
  ...GI_00S_ANCESTORS.map(bg), ...GI_00S_DAMS.map(bg), ...GI_00S,
  ...GI_10S_DAMS.map(bg), ...GI_10S,
  // === import-real-horses.mjs の spread ここから ===
  ...WIKI_40S_ANCESTORS.map(bg), ...WIKI_40S_DAMS.map(bg), ...WIKI_40S,
  ...WIKI_50S_ANCESTORS.map(bg), ...WIKI_50S_DAMS.map(bg), ...WIKI_50S,
  ...WIKI_70S_ANCESTORS.map(bg), ...WIKI_70S_DAMS.map(bg), ...WIKI_70S,
  ...WIKI_80S_ANCESTORS.map(bg), ...WIKI_80S_DAMS.map(bg), ...WIKI_80S,
  ...WIKI_90S_ANCESTORS.map(bg), ...WIKI_90S_DAMS.map(bg), ...WIKI_90S,
  ...WIKI_00S_ANCESTORS.map(bg), ...WIKI_00S_DAMS.map(bg), ...WIKI_00S,
  ...WIKI_10S_ANCESTORS.map(bg), ...WIKI_10S_DAMS.map(bg), ...WIKI_10S,
  ...WIKI_20S,
  ...WIKI_OS_40S.map(os),
  ...WIKI_OS_50S.map(os),
  ...WIKI_OS_70S.map(os),
  ...WIKI_OS_80S.map(os),
  ...WIKI_OS_90S.map(os),
  ...WIKI_OS_00S.map(os),
  ...WIKI_OS_10S.map(os),
  ...WIKI_OS_20S.map(os),
  // === ここまで ===
].map((d) => {
  let o = d;
  const m = AMARE[d.n];
  if (m) {
    const [from, to, lvl, died, big, f] = m;
    o = { ...o, os: true, amare: [from, to], lvl: o.lvl ?? lvl, died: o.died ?? died ?? undefined,
      big: o.big ?? big, f: o.f ?? f ?? undefined };
  }
  if (IMPORTED.has(d.n)) o = { ...o, imp: true };
  const a = ABROAD[d.n];
  if (a) {
    const [from, to, afee, lvl, f, died] = a;
    o = { ...o, os: true, abroad: [from, to], afee, lvl: o.lvl ?? lvl, f: o.f ?? f, died: o.died ?? died ?? undefined };
  }
  if (FACTORS[d.n]) o = { ...o, f: FACTORS[d.n] };
  return o;
});

/** tools/import-wikidata-parents.mjs が読む、Wikidata を重ねる前の表。 */
export const BASE_TABLE = TABLE_BASE;

/**
 * 重ねる祖先を足してよいか。表は馬名で引く（DEFS）ので、同じ名前で年の違う馬が二頭いると
 * 後の方が前の方を潰す（Sailaway 1974 と 1976 で、開始年より後に生まれる実在馬ができた）。
 *   'ok'    足す　 'dup'  同じ馬（生年 ±1）が居る　 'clash'  同名の別の馬が居る
 */
function claim(byName, n, b) {
  const ys = byName.get(n);
  if (ys?.some((y) => Math.abs(y - b) <= 1)) return 'dup';
  if (ys?.length) return 'clash';
  byName.set(n, [b]);
  return 'ok';
}

/**
 * 史実馬の一覧（ahogame-facts.js）から取った父母を重ねる。tools/import-ahogame.mjs が書く。
 * 既にある父母は上書きしない。新しい祖先は表の末尾に足す（途中に入れると世界の乱数がずれる）。
 */
function withAhogame(table) {
  const byName = new Map();
  for (const d of table) byName.set(d.n, [...(byName.get(d.n) ?? []), d.b]);
  // 先に足せる祖先を決める。同名の別馬に潰される祖先は足さず、それを指す父母も外す。
  const drop = new Set();
  const adds = [];
  for (const row of AHO_NEW) {
    const st = claim(byName, row[0], row[1]);
    if (st === 'ok') adds.push(row);
    else if (st === 'clash') drop.add(row[0]);
  }
  const ok = (n) => (n == null || drop.has(n) ? undefined : n);
  const fill = new Map(AHO_FILL.map(([n, b, sire, dam]) => [`${n}|${b}`, { sire: ok(sire), dam: ok(dam) }]));
  const out = table.map((d) => {
    const f = fill.get(`${d.n}|${d.b}`);
    return f ? { ...d, sire: d.sire ?? f.sire, dam: d.dam ?? f.dam } : d;
  });
  for (const [n, b, s, c, sire, dam] of adds) {
    out.push({ n, b, ...(s === '牝' ? { s } : {}), ...(c ? { c } : {}),
      ...(ok(sire) ? { sire } : {}), ...(ok(dam) ? { dam } : {}), bg: true });
  }
  return withAhogameHorses(out);
}

/**
 * 史実馬の一覧の競走馬（ahogame-horses.js）を重ねる。能力値は一覧の値のまま。
 *   表に同じ馬（名前と生年）が居る  → 能力を上書きする。血統用の祖先（bg）だった日本の馬は競走馬にする
 *                                    （bg のままだと世界を作るときに競走馬として作られない。originOf）。
 *   居ない                          → 新しい競走馬として足す。日本の馬は競走馬、海外の馬は os（日本のレースには出ない）。
 * 戦績（出走・勝鞍）は持たない。父母は表か一覧の中に居る名前だけ（居ない名前を書くと realsires.js が落ちる）。
 */
function withAhogameHorses(table) {
  const byName = new Map();
  for (const d of table) byName.set(d.n, [...(byName.get(d.n) ?? []), d.b]);
  const rows = new Map(AHO_HORSES.map((r) => [`${r[0]}|${r[1]}`, r]));
  const traits = ([, , , , , , , lvl, power, guts, wit, sound, spirit, surf, dist, range, style, growth]) => ({
    lvl, ab: { power, guts, wit }, sound, spirit, surf, dist, range,
    ...(style ? { style } : {}), ...(growth ? { growth } : {}),
  });
  const out = table.map((d) => {
    const r = rows.get(`${d.n}|${d.b}`);
    if (!r) return d;
    rows.delete(`${d.n}|${d.b}`);
    const o = { ...d, ...traits(r) };
    // 日本の馬：血統用の祖先だった馬は競走馬にする。
    // 海外の一覧の馬は旗に触らない。os を付けると 8 歳までは世界を作るときに作られなくなる
    // （一覧にはブライアンズタイムのような輸入馬も載っていて、1990 年開始で居なくなった）。
    if (!r[6] && o.bg && !o.os && d.lvl == null) delete o.bg;
    return o;
  });
  const fresh = [];
  for (const r of rows.values()) {
    if (claim(byName, r[0], r[1]) === 'ok') fresh.push(r);
  }
  const has = (n, child) => n && (byName.get(n) ?? []).some((y) => child - y >= 2 && child - y <= 30);
  for (const r of fresh) {
    const [n, b, s, c, sire, dam, osf] = r;
    out.push({ n, b, ...(s && s !== '牡' ? { s } : {}), ...(c && c !== '鹿毛' ? { c } : {}),
      ...(has(sire, b) ? { sire } : {}), ...(has(dam, b) ? { dam } : {}),
      ...traits(r), ...(osf ? { bg: true, os: true } : {}) });
  }
  return out;
}


/**
 * Wikidata から補った父母を重ねる（wikidata-parents.js は tools/import-wikidata-parents.mjs が書く）。
 * 既にある父母は上書きしない（史実馬の一覧で埋まった分が先）。新しい祖先は表の末尾に足す。
 * 英語名の祖先は、史実馬の一覧にカタカナ名があればそちらへ直す。同じ馬が一覧からも来ていたら足さない
 * （二頭に割れて、系統の大きさとインブリードの数が狂う。落とし穴 45）。
 */
function withWikidata(table) {
  const alias = new Map(AHO_ALIAS);
  const byName = new Map();
  for (const d of table) byName.set(d.n, [...(byName.get(d.n) ?? []), d.b]);
  // 英語名 → 最終的な名（null は同名の別馬に潰されるので足さない）。カタカナ名が別の年の馬と衝突するなら英語名のまま。
  const final = new Map();
  const adds = [];
  for (const row of WD_NEW) {
    const [n, b] = row;
    const k = alias.get(n);
    let name = n;
    if (k && (!byName.has(k) || byName.get(k).some((y) => Math.abs(y - b) <= 1))) name = k;
    const st = claim(byName, name, b);
    final.set(n, st === 'clash' ? null : name);
    if (st === 'ok') adds.push([name, ...row.slice(1)]);
  }
  const fin = (n) => (n == null ? undefined : final.has(n) ? final.get(n) ?? undefined : alias.get(n) ?? n);
  const fill = new Map(WD_FILL.map(([n, b, sire, dam]) => [`${n}|${b}`, { sire: fin(sire), dam: fin(dam) }]));
  const out = table.map((d) => {
    const f = fill.get(`${d.n}|${d.b}`);
    return f ? { ...d, sire: d.sire ?? f.sire, dam: d.dam ?? f.dam } : d;
  });
  for (const [n, b, s, sire, dam] of adds) {
    out.push({ n, b, ...(s === '牝' ? { s } : {}), ...(fin(sire) ? { sire: fin(sire) } : {}), ...(fin(dam) ? { dam: fin(dam) } : {}), bg: true });
  }
  return out;
}
/**
 * 英語名のままの馬の名前をカタカナにする（katakana-names.js）。名前・父・母をまとめて置き換える。
 * 表は馬名で引くので、カタカナ名が表に既にある名前と衝突するときは、同じ馬かどうかを決める：
 *   英語名の馬の生年は子から推した値（名前だけの祖先）のことが多く、実際の生年とずれる（Nearco 1938 と ネアルコ 1935）。
 *   そこで生年の一致ではなく、既にあるカタカナ名の馬が、英語名の馬の子すべての親として成り立つか
 *   （親子の年齢差 2〜30 歳）で見る。成り立つ馬が一頭に決まれば同じ馬とみなし、英語名の方を捨てて参照を
 *   カタカナ名へ向ける（二頭に割れない）。成り立たなければ別の馬なので、カタカナ名に生年を添えて区別する（パレオ（1952））。
 */
function withKatakana(table) {
  const kana = new Map(KATAKANA);
  const byName = new Map();
  for (const d of table) byName.set(d.n, [...(byName.get(d.n) ?? []), d]);
  const kids = new Map();      // 親の名 → 子の生年
  for (const d of table) for (const p of [d.sire, d.dam]) if (p) kids.set(p, [...(kids.get(p) ?? []), d.b]);
  const rename = new Map();    // 英語名 → 最終的な名
  const merge = new Map();     // 捨てる英語名の馬（名|生年）→ 残すカタカナ名の馬
  for (const d of table) {
    const k = kana.get(d.n);
    if (!k) continue;
    const others = byName.get(k);
    if (!others) { byName.set(k, [d]); rename.set(d.n, k); continue; }
    const cs = kids.get(d.n) ?? [];
    const ok = others.filter((o) => (cs.length ? cs.every((c) => c - o.b >= 2 && c - o.b <= 30) : Math.abs(o.b - d.b) <= 1));
    ok.sort((x, y) => Math.abs(x.b - d.b) - Math.abs(y.b - d.b));
    if (!ok.length || (ok.length > 1 && Math.abs(ok[0].b - d.b) === Math.abs(ok[1].b - d.b))) {
      // 同名の別の馬（日本の馬名は年代をまたいで再登録される）。カタカナ名に生年を添えて区別する。
      const alt = `${k}（${d.b}）`;
      if (!byName.has(alt)) { byName.set(alt, [d]); rename.set(d.n, alt); }
      continue;
    }
    rename.set(d.n, k);
    merge.set(`${d.n}|${d.b}`, ok[0]);
  }
  const to = (n) => (n == null ? n : rename.get(n) ?? n);
  const out = [];
  const gain = new Map();      // 残すカタカナ名の馬 → 捨てた英語名の馬から引き継ぐ父母
  for (const d of table) {
    const m = merge.get(`${d.n}|${d.b}`);
    if (m) { gain.set(m, { sire: to(d.sire), dam: to(d.dam) }); continue; }
    const n = to(d.n), sire = to(d.sire), dam = to(d.dam);
    out.push(n === d.n && sire === d.sire && dam === d.dam ? d : { ...d, n, ...(sire ? { sire } : {}), ...(dam ? { dam } : {}) });
  }
  // 捨てた馬の父母は、残す馬に無ければ引き継ぐ。
  return out.map((d) => {
    const g = gain.get(table.find((x) => x.n === d.n && x.b === d.b)) ?? null;
    return g && ((!d.sire && g.sire) || (!d.dam && g.dam)) ? { ...d, sire: d.sire ?? g.sire, dam: d.dam ?? g.dam } : d;
  });
}
const TABLE = withKatakana(withWikidata(withAhogame(TABLE_BASE)));

/**
 * 取り込んだ勝ち馬（供用年を持たない日本の牡馬）を種牡馬にする。
 * ウィキペディアの勝ち馬の表には種牡馬としての経歴が無いので、確かな事実から導く。
 *   根拠 1：表の中で別の馬の父として名前が出る（実際に種付けしていた）
 *   根拠 2：GI（JpnI を含む）を勝った
 * 騸馬（せん馬）の見分けは付かないので、GI 馬の中には実際は種牡馬になっていない馬も入る。
 *   供用の始まり：4 歳で引退して翌年から（生年 + 5）。最初の産駒の誕生が早ければその前年。
 *   供用の終わり：最後の産駒の種付けの年か、始めて 10 年のどちらか遅いほう（生年 + 22 が上限）。没年があればそこまで。
 *   種付料 peak：格（GI 220・GII 110・GIII 70）に、素質と産駒の数を足した全盛期の目安（万円）。
 * sd：導いた印。名簿の整理（MAX_STALLIONS）では、手で書いた種牡馬のように外されない扱いにはしない。
 */
const RETIRE = new Map(AHO_RETIRE.map(([n, b, y]) => [`${n}|${b}`, y]));

function withDerivedStuds(table) {
  const kids = new Map();
  for (const d of table) {
    if (!d.sire) continue;
    if (!kids.has(d.sire)) kids.set(d.sire, []);
    kids.get(d.sire).push(d.b);
  }
  const RANK = { GI: 3, JpnI: 3, GII: 2, JpnII: 2, GIII: 1, JpnIII: 1 };
  const BASE = { 3: 220, 2: 110, 1: 70 };
  return table.map((d) => {
    if (d.stud || d.s === '牝' || d.lvl == null || d.bg || d.os || d.imp || d.abroad || d.b < 1955) return d;
    // 親子の年齢差が 2〜30 歳に収まる産駒だけ数える（同じ名の別の馬を拾わない）。
    const ks = (kids.get(d.n) ?? []).filter((b) => b - d.b >= 3 && b - d.b <= 30).sort((a, b) => a - b);
    const big = d.big ?? [];
    const rank = Math.max(0, ...big.map((x) => RANK[x[2]] ?? 0));
    const g1 = big.filter((x) => RANK[x[2]] === 3).length;
    if (!ks.length && rank < 3) return d;
    let from = Math.max(d.b + 3, Math.min(d.b + 5, (ks[0] ?? 9999) - 1));
    if (d.died != null && d.died < from) return d;
    let to = Math.min(d.b + 22, Math.max(from + 9, (ks[ks.length - 1] ?? 0) - 1));
    if (d.died != null) to = Math.min(to, d.died);
    // 若い馬と、最近まで勝ち馬の産駒が出ている馬は 2026 年も供用中とする（終わりを書かない）。
    // 書くと「始めて 10 年」で切れ、イスラボニータ（2011 年生）が 2025 年に退いたことになる。
    else if (d.b >= 2015 || (ks[ks.length - 1] ?? 0) >= 2021 || to >= 2026) to = null;
    // 史実の引退年が一覧にあれば、導いた終わりの年を置き換える（始めて 10 年などの推定より確か）。
    // 終わりが導いた始まりより前なら、始まりを手前へ寄せる（引退年は動かさない）。
    const ry = RETIRE.get(`${d.n}|${d.b}`);
    if (ry != null) {
      to = ry >= 2026 ? null : ry;
      if (to != null && to <= from) from = Math.max(d.b + 3, to - 3);
    }
    const raw = (BASE[rank] ?? 40) + Math.max(0, d.lvl - 0.70) * 1500
      + Math.min(3, Math.max(0, g1 - 1)) * 60 + Math.min(10, ks.length) * 15;
    const peak = Math.round(raw / 10) * 10;
    return { ...d, stud: [from, to], peak, sd: true };
  });
}

export const REAL_HORSES = withDerivedStuds(TABLE);
